import type { EngineInterface, Register } from 'claude-code'

// ターンごとに TypeSafe Jev でプロンプトを判定し、メインループのモデルを切り替える。
// 既定は Sonnet。Jev の確信度が低い・失敗・タイムアウトのときも Sonnet に倒す。

type Tier = 'haiku' | 'sonnet' | 'opus'
type Mode = 'auto' | 'off' | Tier

const MODELS: Record<Tier, string> = {
  haiku: 'claude-haiku-4-5-20251001',
  sonnet: 'claude-sonnet-5-5',
  opus: 'claude-opus-5-5',
}
const DEFAULT_TIER: Tier = 'sonnet'
// 選ばれた選択肢の確率がこれ未満なら既定 (Sonnet) にする
const MIN_PROBABILITY = 0.55
const JEV_TIMEOUT_MS = 4000
const JEV_URL = 'https://api.typesafe.ai/v1/systemone'
const KEYCHAIN_SERVICE = 'TYPESAFE_API_KEY'

type Route = { tier: Tier; reason: string }

const ROUTE_QUESTION = {
  type: 'choice',
  instructions: {
    question:
      'A developer typed `prompt` to a coding agent working in their repository. ' +
      'Which model tier should handle this request? Pick the cheapest tier that can do the job well.',
    note: '`previous_tier` is the tier that handled the previous request; a short follow-up usually needs the same tier.',
  },
  criteria: {
    haiku:
      'Small, mechanical or lookup work: answer a quick factual question, rename or reformat, run a command and report, ' +
      'fix a typo, list files, simple one-file edits with an obvious change, translate or summarize short text.',
    sonnet:
      'Ordinary software work: implement a feature, fix a bug with a findable cause, write tests, explain code, ' +
      'refactor a module, review a diff, or anything that does not clearly fit the other two.',
    opus:
      'Hard work that needs deep reasoning: system or architecture design, debugging an unclear cause across many components, ' +
      'large multi-file refactors or migrations, subtle concurrency, performance or security analysis, or planning an ambiguous open-ended project.',
  },
} as const

let apiKey: string | undefined
let mode: Mode = 'auto'
let lastTier: Tier = DEFAULT_TIER
// turnId -> 判定（turn.start で投げ、turn.step で待つ）
const routes = new Map<string, Promise<Route>>()

async function loadKey($: EngineInterface): Promise<string | undefined> {
  if (apiKey) return apiKey
  const r = await $.process.run(['security', 'find-generic-password', '-s', KEYCHAIN_SERVICE, '-w'])
  if (r.exitCode !== 0) return undefined
  apiKey = r.stdout.trim() || undefined
  return apiKey
}

async function askJev($: EngineInterface, prompt: string): Promise<Route> {
  const key = await loadKey($)
  if (!key) return { tier: DEFAULT_TIER, reason: 'no TYPESAFE_API_KEY' }

  const res = await $.http.fetch(JEV_URL, {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'jev-latest',
      state: { prompt: prompt.slice(0, 8000), previous_tier: lastTier },
      questions: { tier: ROUTE_QUESTION },
    }),
  })
  if (!res.ok) return { tier: DEFAULT_TIER, reason: `jev HTTP ${res.status}` }

  const answer = JSON.parse(res.text)?.answers?.tier as
    | { choice: Tier; probabilities: Record<Tier, number> }
    | undefined
  if (!answer || !(answer.choice in MODELS)) return { tier: DEFAULT_TIER, reason: 'jev: no answer' }

  const p = answer.probabilities[answer.choice] ?? 0
  if (p < MIN_PROBABILITY) {
    return { tier: DEFAULT_TIER, reason: `jev unsure (${answer.choice} ${p.toFixed(2)})` }
  }
  return { tier: answer.choice, reason: `jev ${p.toFixed(2)}` }
}

function route($: EngineInterface, text: string): Promise<Route> {
  if (mode === 'off') return Promise.resolve({ tier: DEFAULT_TIER, reason: 'router off' })
  if (mode !== 'auto') return Promise.resolve({ tier: mode, reason: 'pinned' })
  // 続きのターン（テキストなし）は直前の判定を引き継ぐ
  if (!text.trim()) return Promise.resolve({ tier: lastTier, reason: 'continuation' })

  const fallback = new Promise<Route>(resolve => {
    $.clock.after(JEV_TIMEOUT_MS, () => resolve({ tier: DEFAULT_TIER, reason: 'jev timeout' }))
  })
  const judged = askJev($, text).catch(() => ({ tier: DEFAULT_TIER, reason: 'jev error' }) as Route)
  return Promise.race([judged, fallback])
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'router',
      description: 'Model router: /router [auto|off|haiku|sonnet|opus]',
    })
    return next(e)
  })

  on('command.run', { command: 'router' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === '') return { text: `model-router: mode=${mode}, last=${lastTier}` }
    if (!['auto', 'off', 'haiku', 'sonnet', 'opus'].includes(arg)) {
      return { text: 'usage: /router [auto|off|haiku|sonnet|opus]' }
    }
    mode = arg as Mode
    $.ui.status(`router: ${mode}`)
    return { text: `model-router: mode=${mode}` }
  })

  // 判定はターン開始と同時に投げ、最初のリクエストで待つ
  on('turn.start', async ($, e, next) => {
    const started = await next(e)
    routes.set(started.turnId, route($, e.text))
    return started
  })

  on('turn.step', async function* ($, e, next) {
    // サブエージェントは自分のモデル設定に任せる
    if (e.agentId !== undefined) return yield* next(e)

    const pending = routes.get(e.turnId)
    const { tier, reason } = pending ? await pending : { tier: lastTier, reason: 'no route' }
    lastTier = tier

    if (e.index === 0) $.ui.status(`router: ${tier} (${reason})`)

    // Haiku 4.5 は effort 非対応
    const effort = tier === 'haiku' ? undefined : e.effort
    return yield* next({ ...e, model: MODELS[tier], effort })
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (e.turnId) routes.delete(e.turnId)
    return done
  })
}

